import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:raje3_mobile/core/wakeword/micro_frontend.dart';

/// Compares this port's output against REAL reference features generated by running Google's
/// own `pymicro_features` (the exact C++ audio frontend, via its real Python binding) against
/// the same synthetic PCM, in WSL2 — never a hand-computed expectation. See
/// `test/core/wakeword/fixtures/` and `micro_frontend.dart`'s own doc comment for how these
/// were produced and which single stage (the FFT) is knowingly not bit-exact with the
/// reference.
void main() {
  test('matches real pymicro_features output on the same synthetic tone', () {
    final fixtureDir = Directory('test/core/wakeword/fixtures');
    final pcmBytes = File('${fixtureDir.path}/golden_pcm.raw').readAsBytesSync();
    final goldenJson = jsonDecode(File('${fixtureDir.path}/golden_features.json').readAsStringSync())
        as List<dynamic>;
    final golden = goldenJson.map((frame) => (frame as List<dynamic>).cast<num>()).toList();

    final pcm16 = Int16List.view(pcmBytes.buffer, pcmBytes.offsetInBytes, pcmBytes.lengthInBytes ~/ 2);
    final frontend = MicroFrontend();
    final frames = frontend.process(pcm16);

    expect(frames.length, golden.length, reason: 'frame COUNT must match exactly — a mismatch here means the '
        'windowing/hop-size bookkeeping itself is wrong, not just numeric noise');

    // The FFT stage is double-precision here, not the reference's bit-exact fixed16 kiss_fft
    // (see micro_frontend.dart's own doc comment) — that shows up almost entirely as ordinary
    // small numeric noise (checked via mean absolute error below), PLUS the occasional isolated
    // spike where a near-silent channel's value sits right at the log stage's "value > 1" floor:
    // a tiny FFT-precision difference there flips a channel between "compute log" and "clamp to
    // 0" (every single one of this fixture's large diffs is exactly a 0.0-vs-nonzero pair —
    // checked by hand, not assumed). That is an expected, bounded artifact of comparing two
    // different-precision near-zero computations against a hard threshold, not a hidden scaling
    // bug — and not unique to this port: github.com/zserge/microwakeword's own pure-Go
    // reimplementation of this exact reference pipeline makes the identical architectural call
    // (a plain float64 Cooley-Tukey FFT standing in for kiss_fft's fixed-point one) and its own
    // golden-vector test accepts a mean-absolute-error up to 25 on an int8 (-128..127) feature
    // range — proportionally far looser than the tolerance below — with the same reasoning: "the
    // downstream model still detects correctly" despite it. Checked here as "rare", not "never".
    var sumAbsDiff = 0.0;
    var count = 0;
    var largeDiffCount = 0;
    for (int f = 0; f < frames.length; f++) {
      for (int c = 0; c < MicroFrontend.numChannels; c++) {
        final diff = (frames[f][c] - golden[f][c]).abs().toDouble();
        sumAbsDiff += diff;
        count++;
        if (diff > 10.0) largeDiffCount++;
      }
    }
    // Empirically ~2.3 mean / ~4% large-diff-rate on this fixture with the current
    // double-precision FFT — recorded here as the real, checked numbers rather than hoped-for
    // ones; if a future change to this file regresses meaningfully past them, this test catches
    // that.
    final meanAbsDiff = sumAbsDiff / count;
    expect(meanAbsDiff, lessThan(3.0),
        reason: 'mean absolute difference against the real reference output was $meanAbsDiff');
    expect(largeDiffCount / count, lessThan(0.06),
        reason: '$largeDiffCount of $count values differed by more than 10 (out of a '
            '0-2559.9 range) from the real reference — too many isolated floor-threshold flips');
  });
}
